import numpy as np

def get_last_annotated_beat_timestamp(df, record_id):
    """
    Returns the timestamp of the last annotated beat in the given record_id.

    Args:
        df (pd.DataFrame): The input DataFrame.
        record_id (int): The record_id to filter by.

    Returns:
        float: The timestamp of the last annotated beat, or None if not found.
    """
    try:
        # Validate input parameters
        if df.empty or not isinstance(record_id, int):
            return None

        # Filter the DataFrame for record_id and non-empty annotations
        filtered_df = df.loc[(df['record_id'] == record_id) & (df['annotation'] != '')]

        # Check if filtered DataFrame is not empty
        if not filtered_df.empty:
            # Validate data type of 'time_s' column
            if filtered_df['time_s'].dtype == np.float64:
                # Find the maximum 'time_s' value
                return filtered_df['time_s'].max()
            else:
                return None
        else:
            return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

result = get_last_annotated_beat_timestamp(df, 221)

